"""Driven browser checks for the CEO prototype. Real clicks and key presses through Playwright; every
check reads the DOM. Prints one JSON line per check. Vision is not used: no screenshot is evidence."""
import os, sys, json, re
from playwright.sync_api import sync_playwright
W = os.path.expanduser('~/cold/cand2-r3/out'); URL = lambda p, q='': 'file://' + W + '/' + p + '.html' + q
RES = []; ERRS = []
def check(name, ok, detail=''):
    RES.append({'check': name, 'ok': bool(ok), 'detail': detail}); print(json.dumps(RES[-1]), flush=True)
def watch(page):
    page.on('console', lambda m: ERRS.append(page.url.split('/')[-1][:40] + ' ' + m.type + ': ' + m.text) if m.type == 'error' else None)
    page.on('pageerror', lambda e: ERRS.append(page.url.split('/')[-1][:40] + ' PAGEERROR ' + str(e)))
def dd_pick(page, label, option):
    trig = page.locator('#filter-row .dd', has=page.locator('label', has_text=re.compile('^' + label + '$'))).locator('.trigger')
    trig.click(); page.locator('#filter-row .dd .menu[data-open="true"] li.opt', has_text=option).first.click(); page.wait_for_timeout(300)
def txt(page, sel): return page.locator(sel).first.inner_text().strip()
part = sys.argv[1] if len(sys.argv) > 1 else 'all'
with sync_playwright() as p:
    b = p.chromium.launch(executable_path=os.environ["RENDER_SHELL"])
    ctx = b.new_context(viewport={'width': 1600, 'height': 1000}, accept_downloads=True)
    page = ctx.new_page(); watch(page)
    if part in ('all', 'a'):
        # ---- A. overview: filters re-drive KPIs + charts, persist in URL + storage, survive reload ----
        page.goto(URL('index')); page.evaluate("localStorage.clear()"); page.goto(URL('index')); page.wait_for_timeout(600)
        cash0 = txt(page, '[data-kpi="cash"] .kpi-val'); t0 = txt(page, '[data-chart="exposure-region"] .dv-title'); m0 = page.locator('[data-chart="exposure-region"] svg [data-tip]').count()
        dd_pick(page, 'Region', 'Europe')
        cash1 = txt(page, '[data-kpi="cash"] .kpi-val'); m1 = page.locator('[data-chart="exposure-region"] svg [data-tip]').count()
        check('A1 region filter re-drives KPI', cash0 != cash1, cash0 + ' -> ' + cash1)
        check('A2 region filter re-drives chart marks', m1 < m0, '%d -> %d marks' % (m0, m1))
        check('A3 filter reflected in URL', 'region=Europe' in page.url, page.url.split('?')[-1])
        page.reload(); page.wait_for_timeout(600)
        check('A4 filter survives reload', txt(page, '[data-kpi="cash"] .kpi-val') == cash1 and 'Europe' in txt(page, '#filter-row .cn-dropdown:nth-child(2) .ddval'), txt(page, '#filter-row .cn-dropdown:nth-child(2) .ddval'))
        navhref = page.locator('#nav-wide a[data-slug="payments"]').get_attribute('href')
        check('A5 nav links carry the shared filters', 'region=Europe' in navhref, navhref)
        dd_pick(page, 'Period', 'Last 7 days')
        pts = page.locator('[data-chart="liquidity-trend"] table.dv-table tbody tr').count()
        check('A6 period filter re-drives the time series (table spine rows)', pts == 7, '%d rows' % pts)
        dd_pick(page, 'Region', 'All regions'); dd_pick(page, 'Period', 'Last 30 days')
        # drill-through: click a region column
        mark = page.locator('[data-chart="exposure-region"] svg rect[data-tip]').first; tip = mark.get_attribute('data-tip')
        mark.click(); page.wait_for_load_state(); page.wait_for_timeout(700)
        reg = re.search(r'region=([^&]+)', page.url); reg = reg and reg.group(1).replace('%20', ' ').replace('+', ' ')
        rows_regions = page.evaluate("() => [...document.querySelectorAll('#tbody tr[data-id]')].length")
        check('A7 exposure chart drills through to risk positions for that region', 'risk.html' in page.url and reg and reg in tip, tip + ' -> ' + page.url.split('/')[-1][:80] + ' rows=%d' % rows_regions)
        allin = page.evaluate("(r) => CEO.F.region === r", reg)
        check('A8 drilled page is scoped to the region', allin, 'F.region=' + str(page.evaluate('CEO.F.region')))
        page.goto(URL('index', '?region=all&entity=all&days=30')); page.wait_for_timeout(600)
        d = page.locator('[data-chart="exposure-ccy"] svg path[data-tip]').first; dtip = d.get_attribute('data-tip')
        pt = page.evaluate("""() => { const p = document.querySelector('[data-chart="exposure-ccy"] svg path[data-tip]'); p.scrollIntoView({block:'center'});
          const a = (parseFloat(p.dataset.a1) + parseFloat(p.dataset.a2)) / 2 * Math.PI / 180, r = (parseFloat(p.dataset.ro) + parseFloat(p.dataset.ri)) / 2;
          const svg = p.ownerSVGElement, q = svg.createSVGPoint(); q.x = parseFloat(p.dataset.cx) + r * Math.cos(a); q.y = parseFloat(p.dataset.cy) + r * Math.sin(a);
          const c = q.matrixTransform(p.getScreenCTM()); return [c.x, c.y]; }""")
        page.mouse.click(pt[0], pt[1]); page.wait_for_timeout(900)
        chip = page.locator('#fbar .fchip').all_inner_texts()
        check('A9 currency donut drills to positions filtered by currency', 'risk.html' in page.url and any(dtip.split(':')[0].split('·')[-1].strip() in c for c in chip), dtip + ' -> chips ' + str(chip))
        page.goto(URL('index')); page.wait_for_timeout(600)
        page.locator('[data-panel="approvals"] button.row').first.click(); page.wait_for_timeout(900)
        check('A10 decision card opens the payment record to act on', 'payments.html' in page.url and page.locator('#sheet.open').count() == 1, txt(page, '#dtitle'))
        page.keyboard.press('Escape'); page.wait_for_timeout(300)
        check('A11 Esc closes the drawer', page.locator('#sheet.open').count() == 0)
        page.goto(URL('index')); page.wait_for_timeout(500)
        page.locator('[data-panel="exceptions"] button.row').first.click(); page.wait_for_timeout(900)
        check('A12 exception card opens the risk record', 'risk.html' in page.url and page.locator('#sheet.open').count() == 1, txt(page, '#dtitle'))
        page.keyboard.press('Escape')
        # theme
        page.goto(URL('index')); page.wait_for_timeout(500)
        bg0 = page.evaluate("getComputedStyle(document.querySelector('.ceo-ground')).backgroundColor")
        page.locator('#title-actions .seg button', has_text='Dark').click(); page.wait_for_timeout(400)
        bg1 = page.evaluate("getComputedStyle(document.querySelector('.ceo-ground')).backgroundColor")
        check('A13 theme switch to dark', page.evaluate("document.documentElement.dataset.theme") == 'dark' and bg0 != bg1, bg0 + ' -> ' + bg1)
        page.goto(URL('accounts')); page.wait_for_timeout(500)
        check('A14 theme persists across pages', page.evaluate("document.documentElement.dataset.theme") == 'dark')
        page.locator('#title-actions .seg button', has_text='Light').click(); page.wait_for_timeout(300)
        # nav collapse
        page.locator('#nav-wide .sn-toggle').click(); page.wait_for_timeout(300)
        w = page.evaluate("document.getElementById('nav-wide').getBoundingClientRect().width")
        page.reload(); page.wait_for_timeout(500)
        w2 = page.evaluate("document.getElementById('nav-wide').getBoundingClientRect().width")
        check('A15 nav collapses to a rail and stays collapsed after reload', w == 64 and w2 == 64, '%s / %s' % (w, w2))
        page.locator('#nav-wide .sn-toggle').click(); page.wait_for_timeout(200)
        page.locator('#nav-wide a[data-slug="fx"]').click(); page.wait_for_load_state(); page.wait_for_timeout(500)
        check('A16 nav navigates and marks current page', 'fx.html' in page.url and page.locator('#nav-wide a[aria-current="page"]').get_attribute('data-slug') == 'fx')
    if part in ('all', 'b'):
        # ---- B. payments: grid search/sort/page/size + approval workflow with validation ----
        page.goto(URL('payments', '?entity=all&region=all&days=30')); page.wait_for_timeout(700)
        n0 = txt(page, '#dgCount')
        page.fill('#dgSearch', 'Pending'); page.press('#dgSearch', 'Enter'); page.wait_for_timeout(200)
        n1 = txt(page, '#dgCount')
        check('B1 grid search filters rows and shows a chip', n0 != n1 and page.locator('#fbar .fchip').count() == 1, n0 + ' -> ' + n1)
        page.locator('#fbar .fchip .x').click(); page.wait_for_timeout(200)
        page.locator('#tbl th[data-key="amount"] .sort').click(); page.wait_for_timeout(200)
        s1 = page.locator('#tbl th[data-key="amount"]').get_attribute('aria-sort'); firsts = page.locator('#tbody tr td.num').first.inner_text()
        check('B2 sort by amount', s1 == 'ascending', s1 + ' first=' + firsts)
        page.locator('#pgList [data-go="next"]').click(); page.wait_for_timeout(200)
        check('B3 paging moves to page 2', txt(page, '#dgRange').startswith('9'), txt(page, '#dgRange'))
        page.select_option('#pp', '24'); page.wait_for_timeout(200)
        check('B4 rows per page', page.locator('#tbody tr[data-id]').count() == 24, txt(page, '#dgRange'))
        page.reload(); page.wait_for_timeout(700)
        check('B5 sort and page size persist across reload', page.locator('#tbl th[data-key="amount"]').get_attribute('aria-sort') == 'ascending' and page.locator('#tbody tr[data-id]').count() == 24, txt(page, '#dgRange'))
        # open a pending payment inside the approver's limit
        pid = page.evaluate("() => CEO_DATA.payments.filter(p => p.status === 'Pending approval' && p.gbp < 5e6)[0].id")
        big_id = page.evaluate("() => (CEO_DATA.payments.filter(p => p.status === 'Pending approval' && p.gbp > 25e6)[0] || {}).id")
        pend0 = txt(page, '[data-kpi="pendingCount"] .kpi-val')
        page.fill('#dgSearch', pid); page.press('#dgSearch', 'Enter'); page.wait_for_timeout(200)
        page.locator('#tbody tr[data-id] td').nth(2).click(); page.wait_for_timeout(700)
        check('B6 row click opens detail drawer with focus inside', page.locator('#sheet.open').count() == 1 and page.evaluate("document.getElementById('sheet').contains(document.activeElement)"), txt(page, '#dtitle'))
        check('B7 background is inert while the drawer is open', page.evaluate("document.getElementById('app').inert") is True)
        page.locator('#cancel').click(); page.wait_for_timeout(200)  # Reject with no note
        check('B8 reject without an audit note is refused with an error', page.locator('#sheet .tx-group.is-error').count() == 1 and page.locator('#sheet textarea[aria-invalid="true"]').count() == 1, page.locator('#sheet .tx-msg').inner_text() if page.locator('#sheet .tx-msg').count() else '')
        page.fill('#sheet textarea', 'Duplicate of an invoice already paid last week.'); page.locator('#cancel').click(); page.wait_for_timeout(500)
        toastt = page.locator('#toastRegion .toast').last.inner_text() if page.locator('#toastRegion .toast').count() else ''
        check('B9 reject with a note records the decision and confirms in a toast', page.locator('#sheet.open').count() == 0 and 'rejected' in toastt.lower(), toastt)
        check('B10 grid row status updates to Rejected', 'Rejected' in page.locator('#tbody tr[data-id]').first.inner_text())
        check('B11 pending KPI re-derives from the decision', txt(page, '[data-kpi="pendingCount"] .kpi-val') != pend0, pend0 + ' -> ' + txt(page, '[data-kpi="pendingCount"] .kpi-val'))
        page.reload(); page.wait_for_timeout(600)
        check('B12 decision persists across reload', page.evaluate("(id) => JSON.parse(localStorage.getItem('ceo-proto-v1')).decisions[id].status", pid) == 'Rejected')
        two = page.evaluate("() => CEO_DATA.payments.filter(p => p.status === 'Pending approval' && p.gbp >= 5e6 && p.gbp <= 25e6)[0].id")
        big_id = page.evaluate("() => CEO_DATA.payments.filter(p => p.status === 'Pending approval' && p.gbp > 25e6)[0].id")
        page.goto(URL('payments', '?open=' + big_id)); page.wait_for_timeout(900)
        page.locator('#act').click(); page.wait_for_timeout(200)
        check('B13 approval above the approver limit is refused', 'exceeds your approval limit' in (page.locator('#sheet .tx-msg').inner_text() if page.locator('#sheet .tx-msg').count() else ''), big_id)
        page.keyboard.press('Escape')
        page.goto(URL('payments', '?open=' + two)); page.wait_for_timeout(900)
        page.locator('#act').click(); page.wait_for_timeout(200)
        check('B13b approving a two-approver payment without an audit note is refused', 'audit note' in (page.locator('#sheet .tx-msg').inner_text() if page.locator('#sheet .tx-msg').count() else ''), two)
        page.fill('#sheet textarea', 'Board-approved capex; second approver is the CFO.'); page.locator('#act').click(); page.wait_for_timeout(400)
        check('B13c approval with a note routes it to the second approver', 'awaiting release' in page.locator('#toastRegion .toast').last.inner_text().lower(), page.locator('#toastRegion .toast').last.inner_text())
        with page.expect_download() as dl:
            page.locator('#title-actions button', has_text='Export CSV').click()
        check('B14 export downloads a CSV of the filtered records', dl.value.suggested_filename.endswith('.csv'), dl.value.suggested_filename)
        # chart control: sort segmented re-renders categories
        before = page.evaluate("[...document.querySelectorAll('[data-chart=\"pending-ccy\"] table.dv-table tbody th')].map(e=>e.textContent)")
        page.locator('[data-chart="pending-ccy"] [data-dv-view-btn="desc"]').click(); page.wait_for_timeout(300)
        after = page.evaluate("[...document.querySelectorAll('[data-chart=\"pending-ccy\"] table.dv-table tbody th')].map(e=>e.textContent)")
        vals = [float(v) for v in page.evaluate("[...document.querySelectorAll('[data-chart=\"pending-ccy\"] table.dv-table tbody td')].map(e=>e.textContent)")]
        check('B15 chart sort control re-orders the bars', vals == sorted(vals, reverse=True) and len(vals) > 1, str(before) + ' -> ' + str(after))
        # legend isolate on the pie
        li = page.locator('[data-chart="status-share"] .dv-leg-item').first; li.click(); page.wait_for_timeout(200)
        check('B16 legend isolate works on a rebuilt legend', li.get_attribute('aria-pressed') == 'true', li.inner_text())
        # tooltip: hover a mark
        m = page.locator('[data-chart="pending-ccy"] svg rect[data-tip]').first; m.hover(); page.wait_for_timeout(300)
        tipshown = page.evaluate("() => { const t = document.getElementById('dvTip'); return t && t.classList.contains('on') ? [t.textContent, getComputedStyle(t).visibility, getComputedStyle(t).opacity] : [] }")
        check('B17 hovering a mark shows its tooltip', len(tipshown) > 0, str(tipshown))
    if part in ('all', 'c'):
        # ---- C. risk acknowledgement, trade amendment, liquidity validation, messages form, settings ----
        page.goto(URL('risk', '?entity=all&region=all&days=30')); page.wait_for_timeout(700)
        br0 = txt(page, '[data-kpi="breaches"] .kpi-val')
        xid = page.evaluate("() => CEO_DATA.exceptions.filter(x => x.severity === 'Breach')[0].id")
        page.goto(URL('risk', '?open=' + xid)); page.wait_for_timeout(900)
        page.fill('#sheet textarea', 'too short'); page.locator('#act').click(); page.wait_for_timeout(200)
        check('C1 acknowledgement needs a 15-character audit note', page.locator('#sheet .tx-group.is-error').count() == 1)
        page.fill('#sheet textarea', 'Reducing the deposit with this bank by Friday; treasury to confirm.'); page.locator('#act').click(); page.wait_for_timeout(500)
        check('C2 acknowledgement recorded; breach count re-derives', txt(page, '[data-kpi="breaches"] .kpi-val') != br0, br0 + ' -> ' + txt(page, '[data-kpi="breaches"] .kpi-val'))
        page.goto(URL('trade')); page.wait_for_timeout(600)
        page.fill('#dgSearch', 'Issued'); page.press('#dgSearch', 'Enter'); page.wait_for_timeout(200)
        page.locator('#tbody tr[data-id] td').nth(2).click(); page.wait_for_timeout(700)
        page.fill('#sheet textarea', 'Extend expiry by 60 days to match the shipment.'); page.locator('#act').click(); page.wait_for_timeout(400)
        t = page.locator('#toastRegion .toast').last.inner_text()
        check('C3 trade amendment raises a service request', 'SR-' in t, t)
        page.goto(URL('messages')); page.wait_for_timeout(700)
        check('C4 the raised request appears under service requests', page.locator('[data-panel="requestList"] .title', has_text='Amend').count() >= 1)
        page.locator('[data-panel="requestForm"] button', has_text='Submit request').click(); page.wait_for_timeout(300)
        errs = page.locator('[data-panel="requestForm"] [aria-invalid="true"]').count()
        check('C5 empty service request is refused field by field', errs >= 3 and page.locator('[data-panel="requestForm"] .err-msg').count() == 1 and page.locator('[data-panel="requestForm"] .tx-group.is-error').count() == 1, '%d invalid fields' % errs)
        page.locator('[data-panel="requestForm"] .dd .trigger').first.click(); page.locator('[data-panel="requestForm"] .dd .menu[data-open="true"] li.opt', has_text='Payment investigation').click()
        page.fill('#sr-subject', 'Trace a missing USD receipt'); page.fill('[data-panel="requestForm"] textarea', 'Customer says USD 1.2m was sent on 22 Sep; not yet credited to AC-012.')
        n0 = page.locator('[data-panel="requestList"] li').count()
        page.locator('[data-panel="requestForm"] button', has_text='Submit request').click(); page.wait_for_timeout(400)
        check('C6 valid service request is added to the list', page.locator('[data-panel="requestList"] li').count() == n0 + 1)
        page.locator('[data-panel="inbox"] button.row').first.click(); page.wait_for_timeout(600)
        check('C7 opening a message marks it read', page.locator('#sheet.open').count() == 1)
        page.locator('#cancel').click(); page.wait_for_timeout(200)
        page.goto(URL('liquidity')); page.wait_for_timeout(600)
        page.fill('#dgSearch', 'Overdraft'); page.press('#dgSearch', 'Enter'); page.wait_for_timeout(200)
        page.locator('#tbody tr[data-id] td').nth(2).click(); page.wait_for_timeout(600)
        page.fill('#sheet textarea', 'Draw 5m for payroll timing.'); page.locator('#act').click(); page.wait_for_timeout(200)
        check('C8 drawdown on an uncommitted line is refused', 'uncommitted' in (page.locator('#sheet .tx-msg').inner_text() if page.locator('#sheet .tx-msg').count() else ''))
        page.keyboard.press('Escape')
        page.goto(URL('accounts')); page.wait_for_timeout(600)
        page.locator('#tbl thead tr.cols th[data-key="date"]').focus()   # the grid's roving tab stop
        page.keyboard.press('ArrowDown'); page.keyboard.press('Enter'); page.wait_for_timeout(600)
        check('C9 keyboard: Enter on a grid cell opens the row detail', page.locator('#sheet.open').count() == 1, txt(page, '#dtitle'))
        page.keyboard.press('Escape'); page.wait_for_timeout(200)
        check('C10 focus returns to the grid after closing', page.evaluate("!!document.activeElement.closest('#tbl')"))
        page.goto(URL('settings')); page.wait_for_timeout(600)
        cb = page.locator('#nt-weekly'); was = cb.is_checked(); page.locator('label[for="nt-weekly"]').click(); page.wait_for_timeout(200)
        page.reload(); page.wait_for_timeout(500)
        check('C11 notification preference persists', page.locator('#nt-weekly').is_checked() != was)
        page.locator('[data-panel="prefs"] button', has_text='Reset prototype data').click(); page.wait_for_timeout(600); page.locator('#act').click(); page.wait_for_timeout(300)
        check('C12 reset clears stored workflow state', page.evaluate("(()=>{const s=JSON.parse(localStorage.getItem('ceo-proto-v1')||'{}'); return !s.decisions || Object.keys(s.decisions).length===0})()"))
        page.goto(URL('reports')); page.wait_for_timeout(600)
        page.locator('[data-panel="reportList"] button.row').first.click(); page.wait_for_timeout(600)
        with page.expect_download() as dl:
            page.locator('#act').click()
        check('C13 report download from the reports list', dl.value.suggested_filename.endswith('.csv'), dl.value.suggested_filename)
        page.locator('.sh-actions button').nth(1).click(); page.wait_for_timeout(600)
        check('C14 profile action opens the (simulated) user summary', page.locator('#sheet.open').count() == 1, txt(page, '#dtitle'))
        page.keyboard.press('Escape')
    check('Z console: zero errors across every driven step', len(ERRS) == 0, str(ERRS[:6]))
    b.close()
ok = sum(1 for r in RES if r['ok']); print(json.dumps({'summary': '%d/%d checks passed' % (ok, len(RES))}))
